    # Extend a diagonal stripe motif across the whole grid.
    # Determine the shortest period along diagonals from observed full diagonal evidence.
    h, w = len(grid), len(grid[0])
    # Find diagonals (c-r) with a single consistent nonzero color.
    known = {}
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                d = c-r
                if d not in known:
                    known[d] = v
    # Select minimum period that makes all observed diagonal labels consistent.
    period = max(h, w)
    for p in range(1, max(h,w)+1):
        ok = True
        for d, v in known.items():
            for e, u in known.items():
                if (d-e) % p == 0 and v != u:
                    ok = False
        if ok:
            period = p
            break
    out = [row[:] for row in grid]
    # For each diagonal with a known residue, extend its color across its cells.
    for r in range(h):
        for c in range(w):
            d = c-r
            matches = [(abs((d-e + period//2) % period - period//2), v) for e,v in known.items()]
            if matches:
                dist = min(x[0] for x in matches)
                colors = {v for x,v in matches if x == dist}
                if len(colors) == 1:
                    out[r][c] = next(iter(colors))
    return out
